// Shared selection controls and modal lifecycle. Opening a picker never focuses a text field.
(function(){
  let serial=0,returnFocus=null,lastActivator=null,activeCombo=null,lockedOverflow=null;
  const string=x=>String(x??'');
  const editable=node=>node?.matches?.('textarea, input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit]):not([type=range]):not([type=color]), [contenteditable="true"]');
  function safeFocus(node){if(!node?.isConnected||editable(node)||node.closest('[hidden],[inert]'))return;try{node.focus({preventScroll:true})}catch{node.focus()}}
  const wrapper=node=>node?.matches?.('[data-mm-combo]')?node:node?.closest?.('[data-mm-combo]');
  const trigger=w=>w?.querySelector('[data-mm-trigger]');
  const search=w=>w?.querySelector('[data-mm-search]');
  const popup=w=>w?.querySelector('.mm-combo-list');
  const valueInput=w=>w?.querySelector('input[type=hidden][name]');
  function optionMarkup(options,value){let previousGroup='';return options.map(o=>{let heading='';if(o.group&&o.group!==previousGroup){previousGroup=o.group;heading=`<span class="mm-combo-group">${esc(o.group)}</span>`}return heading+`<button type="button" role="option" tabindex="-1" aria-selected="${string(o.value)===string(value)}" class="mm-combo-option" data-mm-pick="${esc(o.value)}" data-mm-label="${esc(o.label)}" ${o.disabled?'disabled':''}>${esc(o.label)}</button>`}).join('')+'<span class="mm-combo-empty" hidden>No results found.</span>'}
  function sync(node){const w=wrapper(node);if(!w)return;const value=valueInput(w).value,option=[...w.querySelectorAll('[data-mm-pick]')].find(x=>x.dataset.mmPick===value),label=w.querySelector('[data-mm-value-label]');label.textContent=option?.dataset.mmLabel||w.dataset.mmPlaceholder;label.classList.toggle('mm-combo-placeholder',!option);w.querySelectorAll('[data-mm-pick]').forEach(x=>x.setAttribute('aria-selected',string(x.dataset.mmPick===value)))}
  function setValue(node,value,options={}){const w=wrapper(node);if(!w)return;const hidden=valueInput(w);hidden.value=string(value);sync(w);if(options.emit){hidden.dispatchEvent(new Event('change',{bubbles:true}));if(hidden.isConnected)hidden.dispatchEvent(new Event('input',{bubbles:true}))}return hidden}
  function setOptions(node,options,value){const w=wrapper(node);if(!w)return;const hidden=valueInput(w);if(value!==undefined)hidden.value=string(value);else if(!options.some(o=>string(o.value)===hidden.value))hidden.value='';const hadOptionFocus=document.activeElement?.matches?.('[data-mm-pick]')&&w.contains(document.activeElement);w.querySelector('.mm-combo-options').innerHTML=optionMarkup(options,hidden.value);sync(w);filterOptions(w);if(activeCombo===w){position(w);if(hadOptionFocus)safeFocus(trigger(w))}}
  function filterOptions(w){const query=search(w).value.toLocaleLowerCase().trim();let count=0;w.querySelectorAll('[data-mm-pick]').forEach(o=>{o.hidden=!(window.UKI18n?UKI18n.matches(o.dataset.mmLabel,query):o.dataset.mmLabel.toLocaleLowerCase().includes(query));if(!o.hidden)count++});w.querySelectorAll('.mm-combo-group').forEach(o=>{let next=o.nextElementSibling,hasVisible=false;while(next&&!next.classList.contains('mm-combo-group')){if(next.matches('[data-mm-pick]:not([hidden])'))hasVisible=true;next=next.nextElementSibling}o.hidden=!hasVisible});w.querySelector('.mm-combo-empty').hidden=count>0}
  function viewport(){const v=window.visualViewport;return{left:v?.offsetLeft||0,top:v?.offsetTop||0,width:v?.width||window.innerWidth,height:v?.height||window.innerHeight}}
  function updateViewport(){const v=viewport();document.documentElement.style.setProperty('--mm-viewport-height',v.height+'px');document.documentElement.style.setProperty('--mm-viewport-top',v.top+'px');if(activeCombo)position(activeCombo)}
  function position(w){
    if(!w?.isConnected){closeAll();return}
    const p=popup(w),rect=trigger(w).getBoundingClientRect(),v=viewport(),gap=6,minTop=v.top+8,maxBottom=v.top+v.height-8;
    const outside=rect.bottom<v.top||rect.top>maxBottom,typing=document.activeElement===search(w);
    if(outside&&!typing){closeAll();return}
    const below=maxBottom-rect.bottom-gap,above=rect.top-minTop-gap,up=below<180&&above>below,space=Math.max(0,up?above:below);
    const floating=outside||space<100,height=Math.min(340,floating?Math.max(0,v.height-16):space),width=Math.min(Math.max(rect.width,180),Math.max(0,v.width-16));
    const left=Math.max(v.left+8,Math.min(rect.left,v.left+v.width-width-8));
    Object.assign(p.style,{position:'fixed',left:left+'px',width:width+'px',maxHeight:height+'px',top:floating?minTop+'px':up?'auto':Math.max(minTop,rect.bottom+gap)+'px',bottom:!floating&&up?Math.max(0,window.innerHeight-rect.top+gap)+'px':'auto'});
  }

  function closeCombo(w,{restore=false}={}){if(!w)return;const p=popup(w);if(p)p.hidden=true;trigger(w)?.setAttribute('aria-expanded','false');if(activeCombo===w)activeCombo=null;if(editable(document.activeElement)&&w.contains(document.activeElement))document.activeElement.blur();if(restore)safeFocus(trigger(w))}
  function closeAll(except){document.querySelectorAll('[data-mm-combo]').forEach(w=>{if(w!==except)closeCombo(w)})}
  function open(node,{keyboard=false,last=false}={}){const w=wrapper(node);if(!w||trigger(w)?.disabled)return;closeAll(w);sync(w);const input=search(w);input.value='';filterOptions(w);activeCombo=w;popup(w).hidden=false;trigger(w).setAttribute('aria-expanded','true');if(editable(document.activeElement))document.activeElement.blur();safeFocus(trigger(w));position(w);if(keyboard){const available=[...w.querySelectorAll('[data-mm-pick]:not([hidden]):not(:disabled)')];safeFocus(last?available.at(-1):available[0])}}
  window.MMWidgets={combo(name,label,options,value='',placeholder='Select an option'){
    const key='mm-combo-'+(++serial),selected=options.find(o=>string(o.value)===string(value));
    return `<label class="mm-combo-label">${esc(label)}<span class="mm-combo" data-mm-combo data-mm-placeholder="${esc(placeholder)}"><input type="hidden" name="${esc(name)}" value="${esc(value)}"><button id="${key}" type="button" class="mm-combo-input mm-combo-trigger" data-mm-toggle data-mm-trigger role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-controls="${key}-options"><span data-mm-value-label class="${selected?'':'mm-combo-placeholder'}">${esc(selected?.label||placeholder)}</span><span aria-hidden="true" class="mm-combo-chevron">⌄</span></button><span class="mm-combo-list" id="${key}-popup" hidden><span class="mm-combo-search"><input type="search" data-mm-search autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="Search ${esc(label.replace(/\*/g,'').trim())}" placeholder="Search..."></span><span class="mm-combo-options" id="${key}-options" role="listbox" aria-label="${esc(label.replace(/\*/g,'').trim())}">${optionMarkup(options,value)}</span></span></span></label>`;
  },setValue,setOptions,sync,open,closeAll};
  window.addEventListener('click',e=>{const action=e.target.closest?.('button,a[href],[role=button]');if(action)lastActivator=action;const w=wrapper(e.target);if(!w){closeAll();return}const choice=e.target.closest('[data-mm-pick]');if(choice){if(choice.disabled)return;e.preventDefault();closeCombo(w,{restore:true});setValue(w,choice.dataset.mmPick,{emit:true});return}if(e.target.closest('[data-mm-trigger]')){e.preventDefault();if(popup(w).hidden)open(w);else closeCombo(w,{restore:true})}},true);
  window.addEventListener('change',e=>{if(e.target.matches?.('[data-mm-combo] input[type=hidden][name]'))sync(e.target)},true);
  document.addEventListener('input',e=>{if(e.target.matches('[data-mm-search]')){const w=wrapper(e.target);filterOptions(w);position(w)}});
  window.addEventListener('keydown',e=>{let w=wrapper(e.target)||activeCombo;if(e.key==='Escape'&&activeCombo){e.preventDefault();e.stopImmediatePropagation();closeCombo(activeCombo,{restore:true});return}if(!w)return;const available=()=>[...w.querySelectorAll('[data-mm-pick]:not([hidden]):not(:disabled)')];if(e.target.matches('[data-mm-trigger]')&&['ArrowDown','ArrowUp','Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(!popup(w).hidden&&['Enter',' '].includes(e.key))closeCombo(w,{restore:true});else open(w,{keyboard:true,last:e.key==='ArrowUp'});return}if((!popup(w)?.hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&!editable(e.target))||(e.target.matches('[data-mm-search]')&&['ArrowDown','ArrowUp'].includes(e.key))){const items=available(),i=items.indexOf(e.target);if(items.length){e.preventDefault();e.stopImmediatePropagation();const next=e.key==='Home'?0:e.key==='End'?items.length-1:i<0?(e.key==='ArrowUp'?items.length-1:0):(i+(e.key==='ArrowUp'?-1:1)+items.length)%items.length;safeFocus(items[next]);}return}if(e.key==='Tab'&&!popup(w)?.hidden){e.preventDefault();e.stopImmediatePropagation();const items=[search(w),...available()].filter(node=>node&&!node.closest('[hidden]')),i=items.indexOf(e.target),next=i+(e.shiftKey?-1:1);if(next>=0&&next<items.length){const target=items[next];if(editable(target))target.focus({preventScroll:true});else safeFocus(target)}else{closeCombo(w);safeFocus(trigger(w))}return}},true);
  document.addEventListener('focusin',e=>{if(activeCombo&&!activeCombo.contains(e.target))closeAll()});
  window.addEventListener('resize',updateViewport);
  window.visualViewport?.addEventListener('resize',updateViewport);
  window.visualViewport?.addEventListener('scroll',updateViewport);updateViewport();
  document.addEventListener('scroll',e=>{if(activeCombo&&!popup(activeCombo).contains(e.target))position(activeCombo)},true);

  function lockPage(){const present=!!document.querySelector('.modal-bg');if(present&&lockedOverflow===null){lockedOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}else if(!present&&lockedOverflow!==null){document.body.style.overflow=lockedOverflow;lockedOverflow=null}}
  function dismiss(bg,{restore=true}={}){if(!bg?.isConnected)return;closeAll();bg.remove();modalOpen=!!document.querySelector('.modal-bg');lockPage();if(restore&&!modalOpen)safeFocus(returnFocus)}
  closeModal=function(options={}){const backgrounds=[...document.querySelectorAll('.modal-bg')];if(!backgrounds.length)return;closeAll();backgrounds.forEach(bg=>bg.remove());modalOpen=false;lockPage();if(options.restore!==false)safeFocus(returnFocus)};
  showModal=function(title,body,submit,onSubmit){const prior=returnFocus,candidate=lastActivator?.isConnected?lastActivator:document.activeElement;closeAll();closeModal({restore:false});returnFocus=candidate?.isConnected&&!editable(candidate)?candidate:prior?.isConnected&&!editable(prior)?prior:null;if(editable(document.activeElement))document.activeElement.blur();modalOpen=true;const modalId='mm-dialog-'+(++serial);document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="${modalId}"><header class="modal-head"><h2 id="${modalId}">${title}</h2><button type="button" class="icon-btn" id="modal-close" aria-label="Close">×</button></header><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn" id="modal-cancel">Cancel</button><button type="button" class="btn primary" id="modal-submit">${esc(submit||'Save')}</button></footer></section></div>`);const bg=document.querySelector('.modal-bg'),button=bg.querySelector('#modal-submit'),cancel=()=>dismiss(bg);let pending=false;bg.querySelector('#modal-close').onclick=bg.querySelector('#modal-cancel').onclick=cancel;bg.addEventListener('click',e=>{if(e.target===bg)cancel()});button.onclick=()=>{if(pending||!bg.isConnected)return;let result;try{result=onSubmit?.()}catch(err){console.error(err);window.alert('Unable to save. '+err.message);return}if(result&&typeof result.then==='function'){pending=true;button.disabled=true;result.then(value=>{if(value!==false)dismiss(bg)}).catch(err=>{if(bg.isConnected)window.alert('Unable to save. '+err.message)}).finally(()=>{pending=false;if(button.isConnected)button.disabled=false})}else if(result!==false)dismiss(bg)};bg.querySelector('#modal-form')?.addEventListener('submit',e=>{e.preventDefault();button.click()});lockPage();safeFocus(bg.querySelector('#modal-close'));};
  formModal=function(title,fields,onSubmit,submit='Save Changes'){showModal(title,`<form id="modal-form" class="form two">${fields}</form>`,submit,()=>{const form=document.querySelector('#modal-form');if(!form.reportValidity())return false;return onSubmit(Object.fromEntries(new FormData(form)))})};
  document.addEventListener('keydown',e=>{const bg=[...document.querySelectorAll('.modal-bg')].filter(x=>!x.inert&&!x.hasAttribute('inert')).at(-1);if(!bg)return;if(e.key==='Escape'){e.preventDefault();dismiss(bg)}if(e.key==='Tab'){const focus=[...bg.querySelectorAll('input:not([type=hidden]),select,textarea,button,a[href],[contenteditable=true]')].filter(x=>!x.disabled&&!x.hidden&&x.tabIndex!==-1&&!x.closest('[hidden],[inert]')&&getComputedStyle(x).display!=='none'&&getComputedStyle(x).visibility!=='hidden');if(!focus.length)return;if(!bg.contains(document.activeElement)){e.preventDefault();safeFocus(focus[0])}else if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1).focus({preventScroll:true})}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();safeFocus(focus[0])}}});
  new MutationObserver(()=>{if(activeCombo&&!activeCombo.isConnected)activeCombo=null;lockPage()}).observe(document.body,{childList:true,subtree:true});
})();
